function getHashTarget(href){if(!href||!href.includes("#"))return null;const hash=href.slice(href.indexOf("#"));if(hash.length<2)return null;return document.querySelector(hash);}
function isSamePageLink(href){if(href.startsWith("#"))return true;const page=href.split("#")[0];const current=location.pathname.split("/").pop()||"index.html";return page===current||(current===""&&page==="index.html");}
