function setupRotator(selector,intervalMs){const el=document.querySelector(selector);if(!el)return;const words=(el.dataset.rotate||"").split("|").filter(Boolean);if(words.length<2)return;let index=0;setInterval(()=>{el.classList.add("is-fading");setTimeout(()=>{index=(index+1)%words.length;el.textContent=words[index];el.classList.remove("is-fading");},350);},intervalMs);}
setupRotator(".hero-verb",2800);setupRotator(".hero-object",3200);setupRotator(".hero-target",3600);const testimonials=[...document.querySelectorAll(".testimonial")];const dotsContainer=document.querySelector("[data-dots-testimonials]");if(testimonials.length>1&&dotsContainer){let current=0;testimonials.forEach((_,i)=>{const dot=document.createElement("button");dot.type="button";dot.setAttribute("aria-label",`Avis ${i + 1}`);if(i===0)dot.classList.add("is-active");dot.addEventListener("click",()=>goTo(i));dotsContainer.appendChild(dot);});const dots=[...dotsContainer.querySelectorAll("button")];function goTo(i){testimonials.forEach((t,idx)=>t.classList.toggle("is-active",idx===i));dots.forEach((d,idx)=>d.classList.toggle("is-active",idx===i));current=i;}
setInterval(()=>{goTo((current+1)%testimonials.length);},6000);}
const form=document.querySelector(".contact-form");form?.addEventListener("submit",(e)=>{e.preventDefault();alert("Merci ! Ceci est une démo, branchez ce formulaire à votre CRM ou backend.");});const newsletter=document.querySelector(".newsletter-form");newsletter?.addEventListener("submit",(e)=>{e.preventDefault();alert("Inscription newsletter, à connecter à votre outil emailing.");});function setupCatalogFilters(){const bar=document.querySelector("[data-catalog-filters]");if(!bar)return;const items=[...document.querySelectorAll("[data-catalog-item]")];const buttons=[...bar.querySelectorAll("[data-filter]")];function applyFilter(filter){buttons.forEach((btn)=>{btn.classList.toggle("is-active",btn.dataset.filter===filter);});items.forEach((item)=>{const match=filter==="all"||item.dataset.catalogItem===filter;item.classList.toggle("is-hidden",!match);});}
bar.addEventListener("click",(e)=>{const btn=e.target.closest("[data-filter]");if(!btn)return;const filter=btn.dataset.filter;applyFilter(filter);history.replaceState(null,"",filter==="all"?location.pathname:`#${filter}`);});const hash=location.hash.replace("#","");if(hash&&buttons.some((b)=>b.dataset.filter===hash)){applyFilter(hash);}}
setupCatalogFilters();function setupScrollReveal(){if(window.matchMedia("(prefers-reduced-motion: reduce)").matches)return;document.documentElement.classList.add("js-reveal");const staggerSelectors=[".catalog-steps .catalog-step",".services-stack .service-row",".machines-header__inner > *",".machines-grid .machine-item",".machines-cta",".stats-grid .stat",".eco-list li",".home-bcorp__cards .home-bcorp__card",".contact-info__lead",".contact-offices .contact-office",".contact-email",".logos-row .client-logo-wrap",".about-pillars .about-pillar",".about-commitments .about-commitment",".about-values-grid .catalog-benefit",];const singleSelectors=[".page-hero__inner",".catalog-steps",".catalog-filters",".catalog-benefits",".catalog-cta-band",".about-section-header",".about-cert__inner",".about-bcorp__inner",".home-bcorp__visual",".home-bcorp__content > *",".about-cta",".hero-content > *",".hero-visual",".section-title",".section-lead",".testimonials",".carousel-dots",".section--logos .eyebrow",".section--logos .logos-row",".section--cta .container > *",".contact-header",".contact-form",".footer-newsletter-band__inner",".footer-brand",".footer-nav .footer-col",".footer-bottom__inner",];const seen=new Set();function isInsideMarked(el){let node=el.parentElement;while(node){if(seen.has(node))return true;node=node.parentElement;}
return false;}
function mark(el,variant){if(!el||seen.has(el)||isInsideMarked(el))return;seen.add(el);el.classList.add("reveal");if(variant)el.classList.add(variant);}
function stagger(selector,step=85,max=480){document.querySelectorAll(selector).forEach((el,i)=>{mark(el);el.style.setProperty("--reveal-delay",`${Math.min(i * step, max)}ms`);});}
staggerSelectors.forEach((selector)=>stagger(selector));let servicesPanelIndex=0;document.querySelectorAll(".services-panel > *").forEach((el)=>{if(el.classList.contains("services-highlights")){el.querySelectorAll("li").forEach((li)=>{mark(li);li.style.setProperty("--reveal-delay",`${Math.min(servicesPanelIndex * 85, 480)}ms`);servicesPanelIndex+=1;});return;}
mark(el);el.style.setProperty("--reveal-delay",`${Math.min(servicesPanelIndex * 85, 480)}ms`);servicesPanelIndex+=1;});document.querySelectorAll(".split-section > :first-child > *").forEach((el,i)=>{mark(el);el.style.setProperty("--reveal-delay",`${Math.min(i * 85, 340)}ms`);});document.querySelectorAll(".split-section > :last-child:not(:first-child)").forEach((el)=>{if(el.matches("ul, ol"))return;mark(el,"reveal--right");});singleSelectors.forEach((sel)=>{document.querySelectorAll(sel).forEach((el)=>mark(el));});const targets=[...document.querySelectorAll(".reveal")];if(!targets.length)return;const observer=new IntersectionObserver((entries)=>{entries.forEach((entry)=>{if(!entry.isIntersecting)return;entry.target.classList.add("is-visible");observer.unobserve(entry.target);});},{root:null,rootMargin:"0px 0px -6% 0px",threshold:0.05});targets.forEach((el)=>observer.observe(el));}
function parseCountValue(text){const match=text.trim().match(/^(\d+)(.*)$/);if(!match)return null;return{target:parseInt(match[1],10),suffix:match[2]||""};}
function formatCountValue(value,suffix){return`${value}${suffix}`;}
function animateCountUp(el,target,suffix,delay,duration){const run=()=>{const start=performance.now();function tick(now){const progress=Math.min((now-start)/duration,1);const eased=1-Math.pow(1-progress,3);el.textContent=formatCountValue(Math.round(eased*target),suffix);if(progress<1)requestAnimationFrame(tick);}
requestAnimationFrame(tick);};if(delay)window.setTimeout(run,delay);else run();}
function prepareCountElement(el,parsed,reduceMotion){el.dataset.countTarget=String(parsed.target);el.dataset.countSuffix=parsed.suffix;if(!reduceMotion&&parsed.target>0){el.textContent=formatCountValue(0,parsed.suffix);}}
function runCountElement(el,delay,duration){const target=parseInt(el.dataset.countTarget,10);const suffix=el.dataset.countSuffix||"";if(!Number.isFinite(target))return;if(target===0){el.textContent=formatCountValue(0,suffix);return;}
animateCountUp(el,target,suffix,delay,duration);}
function setupMachineStatCounters(){const items=[...document.querySelectorAll(".machine-item")].filter((item)=>item.querySelector(".machine-item__stat-value"));if(!items.length)return;const reduceMotion=window.matchMedia("(prefers-reduced-motion: reduce)").matches;items.forEach((item)=>{const values=[...item.querySelectorAll(".machine-item__stat-value")];if(!values.length)return;values.forEach((el)=>{const parsed=parseCountValue(el.textContent);if(!parsed)return;prepareCountElement(el,parsed,reduceMotion);});if(reduceMotion)return;const observer=new IntersectionObserver((entries)=>{entries.forEach((entry)=>{if(!entry.isIntersecting||item.dataset.statsCounted)return;item.dataset.statsCounted="true";values.forEach((el,i)=>{if(!el.dataset.countTarget)return;const target=parseInt(el.dataset.countTarget,10);const duration=Math.min(1600,700+target*5);runCountElement(el,i*120,duration);});observer.unobserve(item);});},{threshold:0.2,rootMargin:"0px 0px -4% 0px"});observer.observe(item);});}
function setupStatsBandCounters(){const band=document.querySelector(".main--home .stats-band");if(!band)return;const values=[...band.querySelectorAll(".stat-value")];if(!values.length)return;const reduceMotion=window.matchMedia("(prefers-reduced-motion: reduce)").matches;values.forEach((el)=>{const parsed=parseCountValue(el.textContent);if(!parsed)return;prepareCountElement(el,parsed,reduceMotion);});if(reduceMotion)return;const observer=new IntersectionObserver((entries)=>{entries.forEach((entry)=>{if(!entry.isIntersecting||band.dataset.statsCounted)return;band.dataset.statsCounted="true";values.forEach((el,i)=>{if(!el.dataset.countTarget)return;const target=parseInt(el.dataset.countTarget,10);const duration=Math.min(2200,700+target*0.85);runCountElement(el,i*150,duration);});observer.unobserve(band);});},{threshold:0.25,rootMargin:"0px 0px -4% 0px"});observer.observe(band);}
function setupEcoListCounters(){const list=document.querySelector(".main--home #rse .eco-list");if(!list)return;const items=[...list.querySelectorAll("strong")];if(!items.length)return;const reduceMotion=window.matchMedia("(prefers-reduced-motion: reduce)").matches;const parsed=items.map((el)=>{const m=el.textContent.trim().match(/^(\D*?)(\d+)(.*)$/);if(!m)return null;return{el,prefix:m[1]||"",target:parseInt(m[2],10),suffix:m[3]||""};});parsed.forEach((p)=>{if(!p)return;if(!reduceMotion&&p.target>0){p.el.textContent=`${p.prefix}0${p.suffix}`;}});if(reduceMotion)return;const observer=new IntersectionObserver((entries)=>{entries.forEach((entry)=>{if(!entry.isIntersecting||list.dataset.statsCounted)return;list.dataset.statsCounted="true";parsed.forEach((p,i)=>{if(!p||p.target===0)return;const duration=Math.min(1800,700+p.target*6);const run=()=>{const start=performance.now();function tick(now){const progress=Math.min((now-start)/duration,1);const eased=1-Math.pow(1-progress,3);p.el.textContent=`${p.prefix}${Math.round(eased * p.target)}${p.suffix}`;if(progress<1)requestAnimationFrame(tick);}
requestAnimationFrame(tick);};window.setTimeout(run,i*130);});observer.unobserve(list);});},{threshold:0.25,rootMargin:"0px 0px -4% 0px"});observer.observe(list);}
function setupSectionParallax(sectionSelector,bgSelector){const section=document.querySelector(sectionSelector);const bg=document.querySelector(bgSelector);if(!section||!bg)return;const reduceMotion=window.matchMedia("(prefers-reduced-motion: reduce)").matches;const isMobile=window.matchMedia("(max-width: 768px)").matches;if(reduceMotion||isMobile)return;const observer=new IntersectionObserver(([entry])=>{bg.classList.toggle("is-active",entry.isIntersecting);},{threshold:0});observer.observe(section);}
function setupAboutHeroParallax(){const bg=document.querySelector(".about-hero-bg");const sections=document.querySelectorAll(".page-hero--about, .about-mission");if(!bg||!sections.length)return;const reduceMotion=window.matchMedia("(prefers-reduced-motion: reduce)").matches;const isMobile=window.matchMedia("(max-width: 768px)").matches;if(reduceMotion||isMobile)return;const visible=new Set();const observer=new IntersectionObserver((entries)=>{entries.forEach((entry)=>{if(entry.isIntersecting)visible.add(entry.target);else visible.delete(entry.target);});bg.classList.toggle("is-active",visible.size>0);},{threshold:0});sections.forEach((section)=>observer.observe(section));}
function setupCafePopup(){const popup=document.getElementById("cafePopup");if(!popup)return;let dismissed=false;try{dismissed=sessionStorage.getItem("cafePopupClosed")==="1";}catch(e){}
if(dismissed)return;const closeBtn=popup.querySelector(".cafe-popup__close");function show(){popup.hidden=false;popup.setAttribute("aria-hidden","false");requestAnimationFrame(()=>popup.classList.add("is-visible"));}
function hide(){popup.classList.remove("is-visible");popup.setAttribute("aria-hidden","true");try{sessionStorage.setItem("cafePopupClosed","1");}catch(e){}
window.setTimeout(()=>{popup.hidden=true;},450);}
if(closeBtn)closeBtn.addEventListener("click",hide);window.setTimeout(show,4500);}
function setupHeaderScroll(){const header=document.querySelector(".site-header");if(!header)return;const threshold=48;function update(){header.classList.toggle("is-scrolled",window.scrollY>threshold);}
update();window.addEventListener("scroll",update,{passive:true});}
function setupMachineSubnav(){const nav=document.querySelector(".machine-subnav");if(!nav)return;const links=Array.from(nav.querySelectorAll(".machine-subnav__link"));const map=links.map((link)=>{const id=link.getAttribute("href").slice(1);return{link,section:document.getElementById(id)};}).filter((entry)=>entry.section);if(!map.length)return;function setActive(activeLink){links.forEach((l)=>l.classList.toggle("is-active",l===activeLink));}
const offset=120;function update(){let current=map[0];for(const entry of map){if(entry.section.getBoundingClientRect().top<=offset){current=entry;}}
setActive(current.link);}
update();window.addEventListener("scroll",update,{passive:true});}
